import csv
import datetime
import json
import os
import sys

FACT_CONFIG = {
    "offered wage": ("lca_disclosure", "WAGE_RATE_OF_PAY_FROM", "amount"),
    "prevailing wage": ("lca_disclosure", "PREVAILING_WAGE", "amount"),
    "begin date": ("lca_disclosure", "BEGIN_DATE", "date"),
    "end date": ("lca_disclosure", "END_DATE", "date"),
}


def parse_date(val):
    val = val.strip()
    if not val:
        return None
    if "-" in val or "/" in val:
        for fmt in (
            "%Y-%m-%d",
            "%m/%d/%Y",
            "%m/%d/%y",
            "%d-%b-%Y",
            "%Y/%m/%d",
            "%b %d, %Y",
        ):
            try:
                return datetime.datetime.strptime(val, fmt).strftime("%Y-%m-%d")
            except ValueError:
                pass
    try:
        num = float(val)
        dt = datetime.date(1899, 12, 30) + datetime.timedelta(days=int(round(num)))
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        pass
    return val


def parse_amount(val):
    val = val.strip().replace("$", "").replace(",", "")
    if not val:
        return None
    return val


def format_value(val, val_type):
    if val_type == "date":
        return parse_date(val)
    elif val_type == "amount":
        return parse_amount(val)
    return val.strip() if val else None


def load_csv_data(packet_dir):
    data = {}
    for filename in os.listdir(packet_dir):
        doc_name, ext = os.path.splitext(filename)
        if ext.lower() in (".csv", ".tsv"):
            delimiter = "\t" if ext.lower() == ".tsv" else ","
            filepath = os.path.join(packet_dir, filename)
            rows_by_entity = {}
            with open(filepath, "r", encoding="utf-8-sig") as f:
                reader = csv.DictReader(f, delimiter=delimiter)
                for row in reader:
                    case_num = row.get("CASE_NUMBER")
                    if case_num:
                        case_num = case_num.strip()
                        rows_by_entity.setdefault(case_num, []).append(row)
            data[doc_name] = rows_by_entity
    return data


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    packet_data = load_csv_data(packet_dir)

    result = {}
    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        rule_facts = facts_by_rule.get(rule_id, [])
        pair_result = {}

        for fact_name in rule_facts:
            config = FACT_CONFIG.get(fact_name)
            if not config:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name, field_name, val_type = config
            doc_records = packet_data.get(doc_name, {})
            entity_rows = doc_records.get(entity, [])

            values = []
            for row in entity_rows:
                raw_val = row.get(field_name, "")
                cleaned = format_value(raw_val, val_type)
                if cleaned:
                    values.append(cleaned)

            unique_values = sorted(list(set(values)))
            if len(unique_values) == 0:
                pair_result[fact_name] = "ABSENT"
            elif len(unique_values) == 1:
                pair_result[fact_name] = [unique_values[0], doc_name]
            else:
                pair_result[fact_name] = "CONFLICT"

        result[pair] = pair_result

    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

