import csv
import datetime
import json
import re
import sys
from pathlib import Path

RULE_FACTS = {
    "lca.wage_105": {
        "offered wage": ("lca_disclosure", "WAGE_RATE_OF_PAY_FROM", "amount"),
        "prevailing wage": ("lca_disclosure", "PREVAILING_WAGE", "amount"),
    },
    "lca.three_years": {
        "begin date": ("lca_disclosure", "BEGIN_DATE", "date"),
        "end date": ("lca_disclosure", "END_DATE", "date"),
    },
}


def parse_date(val):
    val = val.strip()
    if not val:
        return None

    try:
        f = float(val)
        if 1000 <= f <= 100000:
            base = datetime.date(1899, 12, 30)
            d = base + datetime.timedelta(days=int(round(f)))
            return d.strftime("%Y-%m-%d")
    except ValueError:
        pass

    if len(val) == 8 and val.isdigit():
        try:
            d = datetime.datetime.strptime(val, "%Y%m%d").date()
            return d.strftime("%Y-%m-%d")
        except ValueError:
            pass

    for fmt in (
        "%Y-%m-%d",
        "%m/%d/%Y",
        "%m-%d-%Y",
        "%Y/%m/%d",
        "%B %d, %Y",
        "%b %d, %Y",
    ):
        try:
            d = datetime.datetime.strptime(val, fmt).date()
            return d.strftime("%Y-%m-%d")
        except ValueError:
            pass

    return val


def parse_amount(val):
    val = val.strip()
    if not val:
        return None
    val = re.sub(r"^(?:USD|usd)\s*", "", val)
    val = val.replace("$", "").replace(",", "").strip()
    return val


def get_field_val(row, target_field):
    target_upper = target_field.upper()
    for k, v in row.items():
        if k and k.strip().upper() == target_upper:
            return v
    return None


def get_entity_id(row):
    for k, v in row.items():
        if k and k.strip().upper() == "CASE_NUMBER":
            return v.strip() if v else None
    return None


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = Path(sys.argv[1])
    manifest_path = Path(sys.argv[2])

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    # Load documents from packet directory
    doc_records = {}
    for p in packet_dir.iterdir():
        if p.is_file() and p.suffix.lower() == ".csv":
            doc_stem = p.stem
            entities = {}
            with open(p, "r", encoding="utf-8-sig", errors="replace") as f:
                reader = csv.DictReader(f)
                for row in reader:
                    eid = get_entity_id(row)
                    if eid:
                        entities.setdefault(eid, []).append(row)
            doc_records[doc_stem] = entities

    output = {}
    pairs = manifest.get("pairs", [])
    manifest_facts = manifest.get("facts", {})

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity_id = pair.split("::", 1)
        fact_names = manifest_facts.get(rule_id, [])

        pair_result = {}
        rule_def = RULE_FACTS.get(rule_id, {})

        for fact_name in fact_names:
            if fact_name not in rule_def:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name, field_name, fact_type = rule_def[fact_name]
            entities = doc_records.get(doc_name, {})
            rows = entities.get(entity_id, [])

            if not rows:
                pair_result[fact_name] = "ABSENT"
                continue

            extracted_values = []
            for row in rows:
                raw_val = get_field_val(row, field_name)
                if raw_val is not None and raw_val.strip() != "":
                    if fact_type == "date":
                        parsed = parse_date(raw_val)
                    elif fact_type == "amount":
                        parsed = parse_amount(raw_val)
                    else:
                        parsed = raw_val.strip()

                    if parsed is not None and parsed != "":
                        extracted_values.append(parsed)

            if not extracted_values:
                pair_result[fact_name] = "ABSENT"
            else:
                distinct_values = sorted(list(set(extracted_values)))
                if len(distinct_values) == 1:
                    pair_result[fact_name] = [distinct_values[0], doc_name]
                else:
                    pair_result[fact_name] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

