import csv
import datetime
import json
from pathlib import Path
import sys


def parse_date(val):
    if not val or not val.strip():
        return None
    val = val.strip()

    # Handle Excel serial dates (e.g. 46104)
    try:
        f = float(val)
        if 1000 <= f <= 100000:
            d = datetime.date(1899, 12, 30) + datetime.timedelta(days=int(round(f)))
            return d.strftime("%Y-%m-%d")
    except ValueError:
        pass

    # Handle standard date string formats
    for fmt in (
        "%Y-%m-%d",
        "%m/%d/%Y",
        "%d/%m/%Y",
        "%Y/%m/%d",
        "%B %d, %Y",
        "%b %d, %Y",
    ):
        try:
            return datetime.datetime.strptime(val, fmt).strftime("%Y-%m-%d")
        except ValueError:
            pass

    return val


def parse_amount(val):
    if not val or not val.strip():
        return None
    val = val.strip()
    val = val.replace("$", "").replace(",", "").strip()
    return val if val else None


FACT_FIELD_MAP = {
    "offered wage": ("lca_disclosure", "WAGE_RATE_OF_PAY_FROM", "amount"),
    "prevailing wage": ("lca_disclosure", "PREVAILING_WAGE", "amount"),
    "begin date": ("lca_disclosure", "BEGIN_DATE", "date"),
    "end date": ("lca_disclosure", "END_DATE", "date"),
}


def load_lca_disclosure(packet_dir):
    records_by_case = {}
    doc_path = packet_dir / "lca_disclosure.csv"
    if not doc_path.exists():
        for p in packet_dir.rglob("*"):
            if p.is_file() and p.stem.lower() == "lca_disclosure":
                doc_path = p
                break

    if not doc_path.exists():
        return records_by_case

    with open(doc_path, mode="r", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        for row in reader:
            case_num = row.get("CASE_NUMBER", "").strip()
            if not case_num:
                continue
            if case_num not in records_by_case:
                records_by_case[case_num] = []
            records_by_case[case_num].append(row)

    return records_by_case


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = Path(sys.argv[1])
    manifest_path = Path(sys.argv[2])

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    lca_records = load_lca_disclosure(packet_dir)

    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        needed_facts = facts_spec.get(rule_id, [])

        pair_result = {}
        rows = lca_records.get(entity, [])

        for fact in needed_facts:
            mapping = FACT_FIELD_MAP.get(fact)
            if not mapping:
                pair_result[fact] = "ABSENT"
                continue

            doc_name, col_name, val_type = mapping
            values_found = set()

            for row in rows:
                raw_val = row.get(col_name)
                if val_type == "date":
                    val = parse_date(raw_val)
                elif val_type == "amount":
                    val = parse_amount(raw_val)
                else:
                    val = raw_val.strip() if raw_val else None

                if val is not None:
                    values_found.add(val)

            if len(values_found) == 0:
                pair_result[fact] = "ABSENT"
            elif len(values_found) > 1:
                pair_result[fact] = "CONFLICT"
            else:
                pair_result[fact] = [next(iter(values_found)), doc_name]

        output[pair] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

